-- 023_coach_plans_seed.sql
-- Inserts the 8 hand-authored coach plans (4 phases x 2 users) as INACTIVE
-- rows (is_active=false). plan_data is embedded verbatim from person_a_phases.json
-- / person_b_phases.json (pure {version,phase,total_phases,days} shape — no extra
-- keys). Identity/label/calendar metadata lives in COLUMNS, never in the jsonb.
--
-- plan_data uses DOLLAR-QUOTING ($plandata$...$plandata$) — the notes contain
-- apostrophes and semicolons, and dollar-quoting embeds them with zero escaping.
-- RUN THIS FILE WHOLE in the Supabase SQL Editor (paste + Run). Do NOT run it
-- through a tool that splits the script on ';' — the semicolons inside the
-- plan_data notes would shred the statements. Postgres parses the whole script
-- correctly on its own.
--
-- Requires migration 021 (plan_source, sort_order, phase_weeks) and migration 022
-- (the 5 new library rows the coach plans reference).
--
-- Idempotent + NON-DESTRUCTIVE: each row inserts only if that user has no
-- coach_authored row for that phase yet, so re-running never duplicates and
-- never touches the users' existing auto_generated plans. Nothing is activated
-- here — activation (is_active flip) is the separate "go live" step.
--
-- Calendar (start 24 Sep 2026): only Phase 1 carries start_date now; later
-- phases get their start_date when they are activated.
--   A: P1 wk1-5 (24 Sep) . P2 wk6-11 . P3 wk12-17 . P4 wk18-21 (deload wk21)
--   B: P1 wk1-4 (24 Sep) . P2 wk5-10 . P3 wk11-15 (deload wk13) . P4 wk16-19

-- ─── Coach: A — Recomp V-Taper  (user be213280-323e-40f8-a6f5-3f6c1f84a92b) ───
insert into workout_plans
  (user_id, assessment_id, plan_version, plan_name, plan_data, phase, total_phases,
   weeks_per_phase, phase_weeks, sort_order, start_date, is_active, plan_source)
select 'be213280-323e-40f8-a6f5-3f6c1f84a92b'::uuid, null, 1, 'Coach: A — Recomp V-Taper',
       $plandata${"version":1,"phase":1,"total_phases":4,"days":[{"label":"Upper — Push & Delts","split":"push","exercises":[{"ref":{"type":"library","id":"incline-dumbbell-press"},"sets":3,"rep_low":8,"rep_high":12,"rir":2,"rest_s":120,"progression":"double_progression","note":"30° bench; elbows ~45°, no neck crane, control the stretch.","alternatives":[{"type":"library","id":"machine-chest-press"},{"type":"library","id":"dumbbell-bench-press"}]},{"ref":{"type":"library","id":"machine-shoulder-press"},"sets":3,"rep_low":8,"rep_high":12,"rir":2,"rest_s":120,"progression":"novice_linear","note":"Neutral-grip machine only; stop just short of lockout, ribs down.","alternatives":[{"type":"library","id":"landmine-press"},{"type":"library","id":"neutral_grip_db_ohp"}]},{"ref":{"type":"library","id":"lateral-raises"},"sets":3,"rep_low":12,"rep_high":20,"rir":1,"rest_s":60,"progression":"double_progression","note":"Lead with elbows, no traps shrug; last set to failure.","alternatives":[{"type":"library","id":"cable-lateral-raises"},{"type":"library","id":"reverse-flyes"}]},{"ref":{"type":"library","id":"machine-chest-press"},"sets":2,"rep_low":10,"rep_high":12,"rir":2,"rest_s":90,"progression":"novice_linear","note":"Low-incline pad if available; smooth tempo.","alternatives":[{"type":"library","id":"dumbbell-bench-press"},{"type":"library","id":"push-ups"}]},{"ref":{"type":"library","id":"tricep-pushdown"},"sets":2,"rep_low":10,"rep_high":15,"rir":1,"rest_s":60,"progression":"double_progression","note":"Elbows pinned; last set to failure.","alternatives":[{"type":"library","id":"overhead-tricep-extension"},{"type":"library","id":"skull-crushers"}]},{"ref":{"type":"library","id":"face-pulls"},"sets":3,"rep_low":15,"rep_high":20,"rir":2,"rest_s":60,"progression":"double_progression","note":"MANDATORY prehab; pull to eyes, external-rotate at end.","alternatives":[{"type":"library","id":"reverse-flyes"},{"type":"library","id":"cable-lateral-raises"}]}]},{"label":"Lower A — Quad focus","split":"legs","exercises":[{"ref":{"type":"library","id":"leg-press"},"sets":3,"rep_low":10,"rep_high":15,"rir":2,"rest_s":150,"progression":"novice_linear","note":"Feet mid-platform; knees track toes, full but pain-free ROM.","alternatives":[{"type":"library","id":"hack-squat"},{"type":"library","id":"goblet-squat"}]},{"ref":{"type":"library","id":"romanian-deadlift"},"sets":3,"rep_low":8,"rep_high":12,"rir":2,"rest_s":120,"progression":"novice_linear","note":"Hinge, soft knees, neutral neck; feel hamstring stretch.","alternatives":[{"type":"library","id":"good-mornings"},{"type":"library","id":"leg-curl"}]},{"ref":{"type":"library","id":"leg-extension"},"sets":2,"rep_low":12,"rep_high":15,"rir":1,"rest_s":60,"progression":"double_progression","note":"Pause at top; last set to failure.","alternatives":[{"type":"library","id":"leg-press"},{"type":"library","id":"hack-squat"}]},{"ref":{"type":"library","id":"leg-curl"},"sets":3,"rep_low":10,"rep_high":15,"rir":1,"rest_s":75,"progression":"double_progression","note":"Hams are untrained — extra volume; control the negative.","alternatives":[{"type":"library","id":"romanian-deadlift"},{"type":"library","id":"good-mornings"}]},{"ref":{"type":"library","id":"standing-calf-raise"},"sets":3,"rep_low":10,"rep_high":15,"rir":1,"rest_s":60,"progression":"double_progression","note":"Full stretch at bottom, 1s squeeze up top.","alternatives":[{"type":"library","id":"seated-calf-raise"},{"type":"library","id":"leg-press"}]},{"ref":{"type":"library","id":"dead-bug"},"sets":3,"rep_low":10,"rep_high":12,"rir":2,"rest_s":45,"progression":"rep_progression","note":"Neck-safe core; low back flat to floor throughout.","alternatives":[{"type":"library","id":"bird-dog"},{"type":"library","id":"plank"}]}]},{"label":"Pull — Width & Arms","split":"pull","exercises":[{"ref":{"type":"library","id":"lat-pulldown"},"sets":3,"rep_low":8,"rep_high":12,"rir":2,"rest_s":120,"progression":"novice_linear","note":"V-taper driver; wide-ish grip