low":10,"rep_high":12,"rir":2,"rest_s":120,"progression":"novice_linear","note":"Neutral-grip; keep this pattern grooving safely.","alternatives":[{"type":"library","id":"landmine-press"},{"type":"library","id":"neutral_grip_db_ohp"}]},{"ref":{"type":"library","id":"cable-lateral-raises"},"sets":3,"rep_low":12,"rep_high":20,"rir":1,"rest_s":60,"progression":"double_progression","note":"Constant tension width work; last set to failure.","alternatives":[{"type":"library","id":"lateral-raises"},{"type":"library","id":"reverse-flyes"}]},{"ref":{"type":"library","id":"cable-flyes"},"sets":2,"rep_low":12,"rep_high":15,"rir":1,"rest_s":75,"progression":"double_progression","note":"Set high-to-low for upper chest; stretch under control.","alternatives":[{"type":"library","id":"dumbbell-flyes"},{"type":"library","id":"incline-dumbbell-press"}]},{"ref":{"type":"library","id":"overhead-tricep-extension"},"sets":3,"rep_low":10,"rep_high":15,"rir":1,"rest_s":60,"progression":"double_progression","note":"Long-head stretch; last set to failure.","alternatives":[{"type":"library","id":"tricep-pushdown"},{"type":"library","id":"skull-crushers"}]},{"ref":{"type":"library","id":"face-pulls"},"sets":3,"rep_low":15,"rep_high":20,"rir":2,"rest_s":60,"progression":"double_progression","note":"MANDATORY prehab; owns the cranky shoulder.","alternatives":[{"type":"library","id":"reverse-flyes"},{"type":"library","id":"cable-lateral-raises"}]}]},{"label":"Lower B + Delts","split":"legs","exercises":[{"ref":{"type":"library","id":"goblet-squat"},"sets":3,"rep_low":10,"rep_high":15,"rir":2,"rest_s":120,"progression":"novice_linear","note":"Learn the squat pattern upright; elbows inside knees.","alternatives":[{"type":"library","id":"hack-squat"},{"type":"library","id":"leg-press"}]},{"ref":{"type":"library","id":"hip-thrust"},"sets":3,"rep_low":10,"rep_high":15,"rir":2,"rest_s":90,"progression":"novice_linear","note":"Posterior chain + glutes; chin tucked, ribs down.","alternatives":[{"type":"library","id":"glute-bridge"},{"type":"library","id":"cable-pull-through"}]},{"ref":{"type":"library","id":"leg-curl"},"sets":3,"rep_low":10,"rep_high":15,"rir":1,"rest_s":75,"progression":"double_progression","note":"More hamstring volume; last set to failure.","alternatives":[{"type":"library","id":"romanian-deadlift"},{"type":"library","id":"good-mornings"}]},{"ref":{"type":"library","id":"lateral-raises"},"sets":3,"rep_low":15,"rep_high":20,"rir":1,"rest_s":45,"progression":"double_progression","note":"4th delt session — high-rep pump, strict.","alternatives":[{"type":"library","id":"cable-lateral-raises"},{"type":"library","id":"reverse-flyes"}]},{"ref":{"type":"library","id":"seated-calf-raise"},"sets":3,"rep_low":12,"rep_high":15,"rir":1,"rest_s":60,"progression":"double_progression","note":"Soleus bias; pause stretched.","alternatives":[{"type":"library","id":"standing-calf-raise"},{"type":"library","id":"leg-press"}]},{"ref":{"type":"library","id":"side-plank"},"sets":3,"rep_low":30,"rep_high":45,"rir":2,"rest_s":45,"progression":"rep_progression","note":"Anti-lateral-flexion core; hold seconds not reps.","alternatives":[{"type":"library","id":"plank"},{"type":"library","id":"dead-bug"}]}]}]}$plandata$::jsonb,
       1, 4, 5, 5, 1, date '2026-09-24', false, 'coach_authored'
where not exists (
  select 1 from workout_plans
  where user_id = 'be213280-323e-40f8-a6f5-3f6c1f84a92b'::uuid and plan_source = 'coach_authored' and phase = 1
